// Spanish edition: "Tlamatini, ejecuta la demo <Title>, por favor" (the English form still works).
const m = raw.match(/ejecuta\s+la\s+demo\s+(.+?),\s*por\s+favor/i)
    || raw.match(/run\s+the\s+(.+?)\s+demo/i);

const scrubbed = c.replace(/(?:do\s+not|don['’]?t|never|not)\s+use\b[^.;]*[.;]?/gi, ' ')
    // Spanish edition: "NO uses <...>", "nunca uses <...>" and "sin usar <...>" are the same clauses.
    .replace(/(?:\bno|\bnunca|\bjam[aá]s)\s+(?:uses|utilices)\b[^.;]*[.;]?|\bsin\s+usar\b[^.;]*[.;]?/gi, ' ');

|| /(?:tick|check|enable|turn\s+on)[^.\n]{0,60}step-?by-?step/i.test(c)
// Spanish edition: the toolbar box reads "Paso a paso". Only that box, its mode, a wizard
// named after it or an instruction to tick it counts, so prose ("un paso a la vez") never does.
|| /(?:casillas?|modo|wizard|asistente)\b[^.\n]{0,60}\bpaso\s+a\s+paso\b/i.test(c)
|| /\bpaso\s+a\s+paso\s+(?:wizard|asistente|mode|modo)\b/i.test(c)
|| /\b(?:marca|activa)\b[^.\n]{0,60}\bpaso\s+a\s+paso\b/i.test(c);
